          + '기능화성의 케이던스는 `A7` 의 C♯ 과 G 가 반음으로 벌어지고 좁혀지며 만들어졌다. 모달 곡에는 그 장치가 없다. 대신 쓰는 것이 **모달 케이던스(modal cadence)** 다. 도리안에서는 bVII(`C∆7`)가, 프리지안에서는 bII(`Eb∆7` 에서 `D-7` 로 갈 때의 그 관계)가, 에올리안에서는 bVI 가 중심으로 내려온다. 강도가 약한 대신 조성을 확정하지 않아 모드의 부유감이 유지된다.\n\n'
          + '두 번째 장치는 **페달 포인트(pedal point)** 다. 베이스가 D 를 놓지 않은 채 위에서 화성이 움직이면, 위가 무엇을 하든 귀는 D 를 중심으로 듣는다. 솔로 피아노라면 왼손 5도 D‑A 를 길게 깔고 오른손으로 `C∆7` `Bb∆7` `Eb∆7` 을 평행으로 움직여 보라. 코드 이름이 바뀌어도 곡은 D 를 떠나지 않는다. 이것이 모달 곡에서 긴 구간을 견디는 가장 실전적인 방법이다.\n\n'
