          + '도수로 세어 보면 이유가 보인다. `D-7` 위의 D 펜타토닉은 1‑♭3‑4‑5‑♭7 — 전부 코드 톤과 기본 텐션이라 안전하고 밋밋하다. E 펜타토닉은 D 기준으로 9‑11‑5‑13‑1 이다. ♭3 이 아예 없고 9·11·13 이 전면에 나온다. A 펜타토닉은 5‑♭7‑1‑9‑11 로 중간쯤이다. **같은 모양을 다른 자리에 얹는 것만으로 텐션 구성이 통째로 바뀐다.** 새 스케일을 외운 것이 아니라 이미 가진 도구를 옮긴 것뿐이다.\n\n'
          + '자리를 고르는 규칙은 외우기 쉽다. 마이너 7 코드 위에서는 **루트·2도 위·5도 위** 세 자리가 모두 안전하다. 도미넌트 7 코드 위에서는 **5도 위** 펜타토닉(`G7` 에 D 마이너 펜타토닉)이 9‑11‑5‑13‑1 를 만들어 가장 흔하다. 얼터드 도미넌트 `C7alt` 에서는 **♭6 위**(A♭ 마이너 펜타토닉: A♭‑B‑D♭‑E♭‑G♭)가 ♯5‑7‑♭9‑♯9‑♭13 을 만들어 얼터드 음계와 정확히 겹친다.\n\n'
          + '이것을 **펜타토닉 중첩(pentatonic superimposition)** 이라 한다. 실전에서 쓰는 방식은 한 코러스 안에서 자리를 옮기는 것이다. 8마디 `D-7` 구간에서 앞 4마디는 D, 뒤 4마디는 E 로 옮기면 화성이 고정되어 있어도 색이 이동한다. 앞 모듈의 밀도 곡선과 겹쳐 쓰면 정적 화성이 훨씬 오래 버틴다.'
