        body:
          '메트로놈을 ♩=140 에 맞추고 5/4 로 왼손 `D-7` 쿼탈을 친다. 처음에는 1‑2‑3‑4‑5 를 세게 된다. 세는 한 솔로는 불가능하다. 대신 이렇게 해 보라 — 1박과 4박에만 왼손을 놓는다. 3+2 다. 다음엔 1박과 3박에 놓는다. 2+3 이다. 두 가지를 각각 16마디씩 치면 숫자가 사라지고 **긴 것 하나 + 짧은 것 하나**라는 신체 감각만 남는다.\n\n'
          + '왜 세면 안 되는가. 숫자 세기는 작업 기억을 점유한다. 5를 세는 동안에는 선율을 만들 여유가 없다. 4/4 를 셀 필요가 없는 이유는 이미 몸이 강‑약‑중강‑약 패턴을 알기 때문이다. 변박도 같은 상태로 만들어야 한다. **그룹 분할(grouping)** 을 몸에 심으면 5박이 하나의 단위가 되고, 그때부터 그 위에서 자유롭게 놀 수 있다.\n\n'
          + '7/4 는 분할 선택지가 더 많다. 4+3, 3+4, 2+2+3, 3+2+2. 각각 성격이 다르다 — 4+3 은 4/4 에 3박이 붙은 느낌이라 가장 익숙하고, 2+2+3 은 뒤가 밀리는 추진력이 생긴다. 한 곡 안에서 분할을 바꾸면 마디 길이는 같은데 느낌이 달라진다. 이것이 변박 곡에서 컴핑이 하는 일의 핵심이다.\n\n'
