        body:
          '`C∆7` `A-7` `D-7` `G7` 을 한 마디씩 놓고 왼손만 세 가지로 바꿔 쳐 보라. (1) **루트‑5도**: 1박 C, 3박 G. 코드마다 같은 방식. 가장 단순하고 가장 안 무너진다. (2) **텐스(tenths)**: 1박에 C 와 E 를 10도 간격으로 함께 잡는다(손이 안 닿으면 빠르게 굴린다). 루트와 3음이 동시에 나와 화성이 왼손 하나로 성립한다. (3) **워킹 베이스**: 4분음표로 C‑D‑E‑G 처럼 걸어간다.\n\n'
          + '세 방식은 난이도가 아니라 **용도**가 다르다. 루트‑5도는 오른손이 바쁜 구간에서 쓴다 — 왼손이 단순해야 오른손이 자유롭다. 텐스는 발라드와 루바토에서 쓴다 — 한 번 치고 울리게 두면 베이스와 화성이 동시에 해결된다. 워킹은 미디엄 스윙에서 쓰되 오른손 선율을 단순화해야 한다. **왼손이 복잡해지면 오른손이 단순해지는 총량 관계**가 항상 성립한다.\n\n'
          + '워킹을 왼손 혼자 할 때의 실전 규칙은 두 가지다. 첫째, 각 코드의 1박은 루트로 착지한다. 둘째, 다음 코드 루트로 반음 또는 온음으로 접근한다. 이 두 가지만 지키면 중간 두 박은 코드 톤이나 스케일 음 아무거나로 채워도 된다. L3 의 목표음 조준을 베이스에 적용한 것이며, 원리는 완전히 같다.\n\n'
          + '텐스가 손에 안 닿는 경우가 흔하다. 그때는 **롤(roll)** 로 처리한다 — 루트를 먼저 놓고 페달로 잡은 뒤 3음을 이어 친다. 소리로는 동시에 친 것과 거의 같게 들리고, 오히려 재즈 피아노의 관용적 표현으로 들린다. 손 크기를 이유로 이 기법을 포기할 필요가 전혀 없다.'
