        body:
          '같은 8마디를 세 가지로 쳐 보라. (1) **풀 스트라이드**: 1·2·3·4박 전부 채운다. (2) **하프 스트라이드**: 1박 베이스와 2박 코드만 치고 3·4박은 쉰다. (3) **희소 스트라이드**: 1박 베이스는 매 마디 치되 코드는 두 마디에 한 번만, 그것도 예상 밖의 자리에 놓는다. 셋 다 스트라이드지만 인상이 완전히 다르다.\n\n'
          + '풀 스트라이드는 밀도가 높아 곡 전체에 쓰면 금세 낡게 들린다. 현대적 연주에서 스트라이드는 **한 코러스 전체가 아니라 특정 구간의 장치**로 쓰인다. 마지막 A 섹션, 솔로의 절정, 아웃 코러스 같은 자리에 8마디만 넣으면 강한 대비가 생긴다. 대비가 목적이므로 그 앞 구간은 워킹이나 긴 화음으로 대조를 만들어 둔다.\n\n'
          + '희소 스트라이드는 몽크 계열의 접근이다. 베이스는 시간을 지키되 코드는 예상되는 자리를 피해 놓는다. 청자는 규칙적인 패턴을 기대하다가 어긋난 자리에서 코드를 듣고, 그 어긋남이 스윙감을 만든다. 실행 방법은 단순하다 — 2박 코드를 2박 반이나 4박 뒤쪽으로 옮기고, 어떤 마디에서는 아예 생략한다. **생략이 연주의 일부**라는 감각이 이 스타일의 핵심이다.\n\n'
