        body:
          '`t-misty` 를 친다고 하자. 인트로를 만드는 가장 빠른 방법은 **곡의 마지막 4마디를 가져다 쓰는 것**이다. 턴어라운드 `Eb∆7` `C-7` `F-7` `Bb7` 을 루바토로 한 번 돌리고 첫 코드로 들어간다. 실패할 수 없는 방식이고, 마지막 화성이 이미 곡의 첫 코드로 향하도록 설계되어 있어 착륙이 자연스럽다.\n\n'
