          + '세 번째는 **베이스 하행**이다. 곡 첫 코드의 루트보다 반음 또는 온음 위에서 시작해 걸어 내려온다. 예를 들어 `C∆7` 로 시작하는 곡이면 E♭ → D → D♭ → C 로 내려오면서 위에 임의의 화성을 얹는다. 베이스가 목표를 향해 내려오는 동안 청자는 도착 지점을 예감하고, 도착하는 순간 곡이 시작된다.\n\n'
