          + '어느 것이든 공통 원리는 **밀도가 단조롭게 줄어야 한다**는 것이다. 곡을 끝낸다는 신호는 화성이 아니라 밀도로 전달된다. 마지막 8마디에서 음 개수가 계속 줄고 음역이 좁아지면 청자는 끝을 예감한다. 반대로 마지막에 갑자기 화려해지면 곡이 아직 안 끝난 것으로 들린다. 태그를 반복할 때마다 음을 빼는 것이 이 때문이다.\n\n'
          + '마지막 화음의 보이싱도 정해 두어야 한다. 발라드의 기본형은 `C6/9` — 루트와 5도를 왼손에 넓게, 오른손에 A‑D‑E 또는 E‑A‑D. 메이저 7음은 마지막 화음에서 반음 긴장이 남아 완전히 닫히지 않으므로, 확실히 끝내고 싶으면 6/9 나 9 로 대체한다. 마이너 곡이면 `C-6/9` 나 `C-∆7` 중에서 고른다 — 후자는 여운이 남고 전자는 깨끗이 닫힌다.\n\n'
