        body:
          '플레이어롱의 솔로 트랙이나 다른 연주자의 녹음을 틀고, **코드를 미리 정하지 않은 채** 컴핑해 보라. 규칙은 하나다. 솔리스트가 프레이즈를 끝내면 그 직후 반 박 안에 코드를 하나 놓는다. 프레이즈가 이어지는 동안에는 아무것도 치지 않는다. 8마디 동안 이것만 해 보면 대개 코드를 3~5회 치게 되고, 그 몇 개가 평소의 스무 개보다 음악적으로 들린다.\n\n'
          + '이유는 대화 구조에 있다. 사람은 상대가 말하는 동안 끼어들지 않고 문장이 끝날 때 반응한다. 컴핑도 같다. 솔리스트의 프레이즈 중간에 코드를 넣으면 그것은 반주가 아니라 방해다. 프레이즈 끝의 여백에 넣으면 대답이 된다. **컴핑의 타이밍은 화성이 아니라 상대의 문장 구조가 결정한다.**\n\n'
          + '한 단계 위는 **리듬 모방**이다. 솔리스트가 친 리듬 패턴을 코드로 그대로 되받는다. 솔리스트가 점4분‑8분‑4분을 쳤으면 같은 리듬으로 코드를 놓는다. 음정은 다르지만 리듬이 같으므로 청자는 둘이 연결되어 있다고 듣는다. 한 코러스에 세 번만 넣어도 트리오가 같은 방향을 보고 있다는 인상이 생긴다.\n\n'
