          + '방향 신호도 있다. 밀도를 올리는 것은 "가자"는 신호이고, 갑자기 비우는 것은 "바꾸자"는 신호다. 음역을 올리면 절정으로 향하자는 뜻, 낮은 음역으로 내려가면 정리하자는 뜻으로 대개 통한다. 이 신호는 말로 합의한 것이 아니라 **관습**이고, 녹음을 많이 들은 사람일수록 정확히 읽는다. 그래서 인터플레이 훈련의 절반은 듣기다.\n\n'
          + '혼자 연습할 때는 **자기 자신과 대화**한다. 2마디를 치고 2마디를 쉰 다음, 방금 친 것의 재료 하나를 받아 이어 친다. 녹음해 두었다가 다음 날 그 녹음 위에 응답하는 방법도 좋다. 상대가 없다고 인터플레이를 못 배우는 것이 아니다. 받을 재료를 식별하는 귀가 먼저이고, 사람은 그다음이다.'
