        body:
          '`t-autumn-leaves` A 섹션을 네 번 연달아 연주하되 매번 하나씩만 바꿔라. (1) **음역** — 두 번째는 전체를 한 옥타브 올린다. (2) **밀도** — 세 번째는 음 개수를 절반으로 줄인다. (3) **좌수 스타일** — 네 번째는 스프레드에서 워킹으로 바꾼다. (4) **박자/키** — 다섯 번째는 4/4 를 3/4 로 바꾸거나 반음 위로 이조한다. 각각 8마디면 충분히 들린다.\n\n'
          + '네 손잡이의 효과 크기는 다르다. **음역 이동이 가장 즉각적**이고, 밀도 변화가 가장 안전하며, 좌수 스타일 변경은 양식적 인상을 바꾸고, 박자/키 변경은 가장 강력하지만 준비가 필요하다. 4~5분짜리 편곡이라면 음역과 밀도는 여러 번, 좌수는 한두 번, 박자/키는 많아야 한 번 쓴다. 강한 장치를 자주 쓰면 강함이 사라진다.\n\n'
          + '박자 변경은 절차가 있다. 4/4 를 3/4 로 바꾸면 32마디 곡이 마디 수는 같아도 실제 길이가 줄어든다. 그러면 프레이즈가 어디서 끝나는지 다시 계산해야 한다. 가장 안전한 방법은 **코드 하나당 마디 수를 유지**하는 것이다 — 한 마디에 한 코드였으면 3/4 에서도 한 마디에 한 코드. 멜로디는 그 안에서 재배치한다.\n\n'
          + '이조는 반음 위나 온음 위가 가장 흔하고, 마지막 코러스에서 올리면 절정 효과가 난다. 넘어가는 방법은 두 가지 — 원래 키의 마지막 마디에 새 키의 도미넌트를 놓거나, 반음 위 도미넌트로 밀어 올린다. 이조 후에는 손이 낯선 자리에 놓이므로, **편곡에 이조를 넣었다면 그 키에서 따로 연습**해야 무대에서 무너지지 않는다.'
