          + '작곡에서 가장 흔한 실패는 **화성이 너무 많이 움직이는 것**이다. 배운 리하모니제이션 기법을 다 쓰고 싶어지지만, 코드가 매 박 바뀌면 선율이 설 자리가 없고 연주자도 솔로할 공간이 없다. 좋은 재즈 곡은 대개 **정지 구간과 이동 구간이 교대**한다. 4마디 머물고 4마디 움직이는 식이다. 이 교대가 곡의 형태를 만든다.\n\n'
          + '두 번째 원칙은 **연주자를 위한 여지**다. 재즈 곡은 완결된 작품이 아니라 연주의 출발점이다. 화성이 지나치게 특수하면 솔로하기 어렵고, 결국 아무도 연주하지 않는다. 시작할 때는 **익숙한 진행 70%, 자기 색 30%** 정도가 실용적이다. 특이한 화성은 한두 자리에 집중해 두면 그 자리가 곡의 인상이 된다.\n\n'
          + '세 번째는 **피아노를 전제로 쓰는 것**이다. 선율을 쓸 때 그 아래 보이싱이 어떻게 들어가는지 같이 상상한다. 선율이 계속 중음역에 있으면 왼손 화성과 자리가 겹치고, 선율이 코드의 텐션 음만 쓰면 보이싱에서 그 음을 빼야 해 화성이 얇아진다. **선율을 쓰면서 왼손을 같이 쳐 보는 것**이 가장 확실한 검증이며, 책상이 아니라 건반에서 작곡해야 하는 이유다.'
