          + '자기 곡을 연주할 때 흔한 문제는 **선율을 너무 정확히 치는 것**이다. 작곡한 사람이라 적힌 대로 치게 되는데, 재즈에서 선율은 해석 대상이다. 리듬을 밀거나 당기고, 음을 빼고, 장식을 붙인다. 오히려 남의 곡보다 자유롭게 다뤄도 된다. 자기 곡이므로 무엇이 본질이고 무엇이 표면인지 아는 사람이 자신이다.\n\n'
          + '마지막으로 **제목과 템포를 정한다.** 사소해 보이지만 둘 다 곡의 정체를 결정한다. 같은 곡이 ♩=120 과 ♩=180 에서 완전히 다른 곡이 되며, 어느 쪽이 맞는지는 여러 번 쳐 봐야 안다. 두세 가지 템포로 연주해 녹음하고 고른다. 이 결정을 미루면 연주할 때마다 템포가 달라져 곡이 자리를 잡지 못한다.'
