        body:
          '폼을 놓치는 상황을 일부러 만들어 보라. `t-alone-together` 를 연주하다가 중간에 두 마디를 일부러 빼먹고 계속 친다. 대부분 여기서 멈춘다. 멈추지 않고 돌아오는 절차는 정해져 있다. **첫째, 계속 친다.** 멈추면 밴드 전체가 무너진다. **둘째, 베이스를 듣는다.** 베이스가 루트를 치고 있으므로 지금 어느 코드인지 알 수 있다. **셋째, 가장 가까운 섹션 시작 지점에 맞춰 들어간다.**\n\n'
          + '섹션 시작 지점을 찾는 기준은 **화성 좌표**다. AABA 32마디라면 9마디(두 번째 A), 17마디(브리지), 25마디(마지막 A)가 좌표다. 이 세 지점의 코드를 곡마다 외워 두면 어디서 헤매도 다음 좌표에서 합류할 수 있다. 이것이 L8‑03 의 4층 암보에서 화성 골격을 첫 번째로 두는 이유다.\n\n'
          + '템포가 흔들릴 때는 다르게 대응한다. 빨라졌다면 **음을 줄이고 긴 음을 친다.** 밀도를 낮추면 자연히 느려진다. 느려졌다면 밀도를 올리기보다 **왼손을 확실한 자리(1박·3박)에 다시 놓는다.** 어느 경우든 자기가 템포를 끌어당기려 하면 밴드와 싸우게 되므로, 드럼의 하이햇이나 베이스의 4분음표에 자기를 맞추는 편이 빠르다.\n\n'
