            label: '오프너 후보 — 확실한 미디엄 스윙',
            chords: ['C∆7', 'A7', 'D-7', 'G7'],
            key: 'C',
            voicing: 'rootless-a',
            caption: '1번 곡은 긴장이 가장 높으므로 가장 확실한 곡을 둔다.',
